class Handler
{
    public virtual string Name => "base";
    public string Kind => "handler";
}

sealed class LtiHandler : Handler
{
    public override string Name => "lti";
    public new string Kind => "lti-handler";
}

Handler h = new LtiHandler();
Console.WriteLine(h.Name); // lti — virtual dispatch
Console.WriteLine(h.Kind); // handler — hidden, NOT dispatched

abstract class AuthHandler
{
    public abstract AuthToken Parse(string raw);
    public virtual bool IsExpired(AuthToken token) =>
        token.ExpiresAt < DateTimeOffset.UtcNow;
}

sealed class LtiHandler : AuthHandler
{
    public override AuthToken Parse(string raw) => new AuthToken(raw, "lti");
    public sealed override bool IsExpired(AuthToken token) =>
        base.IsExpired(token); // no further override allowed
}

abstract class TokenParser
{
    public AuthToken Parse(string raw)
    {
        Validate(raw);
        return ParseCore(raw);
    }

    private void Validate(string raw)
    {
        if (string.IsNullOrWhiteSpace(raw))
            throw new ArgumentException("Token required");
    }

    protected abstract AuthToken ParseCore(string raw);
}

abstract class HandlerFactory
{
    public virtual Handler Create() => new Handler("base");
}

sealed class LtiFactory : HandlerFactory
{
    // Override may return a MORE derived type than the base virtual method.
    public override LtiHandler Create() => new LtiHandler("lti");
}

HandlerFactory f = new LtiFactory();
Handler h = f.Create(); // runtime type is LtiHandler
LtiHandler lti = ((LtiFactory)f).Create(); // no cast needed on the override

abstract class Base
{
    protected Base()
    {
        Log(); // virtual call from ctor — dangerous
    }

    protected virtual void Log() => Console.WriteLine("base");
}

sealed class Derived : Base
{
    private readonly string _tenant = "acme";

    protected override void Log() =>
        Console.WriteLine(_tenant.Length); // _tenant still null/default!

    // Fix: make Log non-virtual and call it from Derived ctor after fields init,
    // or use an Initialize() called by factory after construction.
}
